/**
 * 负责独立审核诡术师换位、放逐映射与枪击证据。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { isTricksterPreset } from "../verification/board-support";
import {
  readTricksterExchangeFact,
  readTricksterSkipFact,
  readExileMappingFact,
} from "@ai-werewolf-arena/game-contract/facts/trickster";
import { readMagicianExchangeFact } from "@ai-werewolf-arena/game-contract/facts/magician";
import { Camp, Role, Phase } from "@ai-werewolf-arena/game-contract";
import type { ReproductionRecord } from "./reproduction";
const exchange = "trickster_exchange_committed",
  skip = "trickster_exchange_skipped",
  mapping = "exile_target_mapped";
function check(v: unknown): asserts v {
  if (!v) throw new Error("reproduction_trickster_invalid");
}
function equal(a: unknown, b: unknown): boolean {
  const stable = (v: unknown): unknown =>
    Array.isArray(v)
      ? v.map(stable)
      : v && typeof v === "object"
        ? Object.fromEntries(
            Object.entries(v)
              .sort(([a], [b]) => a.localeCompare(b))
              .map(([k, x]) => [k, stable(x)]),
          )
        : v;
  return JSON.stringify(stable(a)) === JSON.stringify(stable(b));
}
export function validateTricksterRecord(record: ReproductionRecord): void {
  const board = record.metadata.normalizedBoard;
  const owns = board.roleSetups.some((r) => r.role === Role.Trickster && r.count > 0);
  const artifacts =
    record.events.some((e) => [exchange, skip, mapping].includes(e.type)) ||
    record.decisions.some(
      (d) =>
        d.stage === "trickster_exchange" ||
        d.request.allowedTools.includes("swap_exile_targets") ||
        d.request.context.trickster_candidates !== undefined ||
        d.request.context.trickster_may_pass !== undefined,
    ) ||
    record.checkpoints.some((c) =>
      c.players.some((p) => Object.hasOwn(p.privateState, "trickster")),
    );
  if (!owns) {
    check(
      !board.trickster &&
        !artifacts &&
        !record.metadata.players.some((p) => p.role === Role.Trickster),
    );
    return;
  }
  check(isTricksterPreset(board) && !record.metadata.faultPlan && !record.metadata.initialDeal);
  const original = new Map(record.metadata.players.map((p) => [p.id, p]));
  const actors = record.metadata.players.filter((p) => p.role === Role.Trickster);
  check(original.size === 12 && actors.length === 1 && actors[0]!.camp === Camp.Wolf);
  const actor = actors[0]!.id,
    alive = new Set(original.keys()),
    used = new Set<number>();
  const history: Array<{ day: number; pair: [number, number] | null }> = [];
  const histories = [structuredClone(history)],
    living = [[...alive]];
  const facts = new Map<number, { pair: [number, number] | null; index: number }>(),
    skipped = new Set<number>();
  const magic = new Map<number, [number, number] | null>(),
    nightAlive = new Map<number, number[]>([[1, [...alive]]]);
  const resolved = new Set<number>(),
    mapped = new Set<number>();
  let day = 1,
    phase: Phase = Phase.Night,
    expectedExile: number | null = null;
  for (let i = 0; i < record.events.length; i++) {
    const e = record.events[i]!;
    if (e.type === "phase_changed") {
      check(Number.isSafeInteger(e.payload.day) && Number(e.payload.day) > 0);
      day = Number(e.payload.day);
      phase = e.payload.phase as Phase;
      if (phase === Phase.Night) {
        nightAlive.set(day, [...alive]);
        expectedExile = null;
      }
    }
    if (e.type === "magician_exchange_committed") {
      const f = readMagicianExchangeFact(e.type, e.payload);
      check(
        f &&
          phase === Phase.Night &&
          f.day === day &&
          !magic.has(day) &&
          !facts.has(day) &&
          !skipped.has(day),
      );
      magic.set(day, f.pair);
    }
    if (e.type === exchange || e.type === skip) {
      check(phase === Phase.Night && !facts.has(day) && !skipped.has(day) && !resolved.has(day));
      check(Array.isArray(e.audience) && equal(e.audience, [actor]));
      const candidates = [...alive].filter((id) => !used.has(id));
      if (e.type === skip) {
        const f = readTricksterSkipFact(e.type, e.payload);
        check(f && f.actorId === actor && f.day === day);
        check(f.reason === "dead" ? !alive.has(actor) : alive.has(actor) && candidates.length < 2);
        check(!record.decisions.some((d) => d.day === day && d.stage === "trickster_exchange"));
        skipped.add(day);
      } else {
        const f = readTricksterExchangeFact(e.type, e.payload);
        check(
          f && f.actorId === actor && f.day === day && alive.has(actor) && candidates.length >= 2,
        );
        const ds = record.decisions.filter(
          (d) => d.day === day && d.stage === "trickster_exchange",
        );
        check(ds.length === 1);
        const d = ds[0]!;
        const mayPass = !(history.at(-1)?.day === day - 1 && history.at(-1)?.pair === null);
        check(
          d.actorId === actor &&
            d.request.actorId === actor &&
            d.request.phase === Phase.Night &&
            d.request.context.day === day &&
            d.request.context.stage === d.stage,
        );
        check(
          d.request.context.action_failure_policy === "error" &&
            d.request.context.allow_fallback === false &&
            equal(d.request.allowedTools, ["swap_exile_targets"]),
        );
        check(
          equal(d.request.context.trickster_candidates, candidates) &&
            d.request.context.trickster_may_pass === mayPass,
        );
        check(d.outcome.kind === "action" && d.outcome.action?.name === "swap_exile_targets");
        const a = d.outcome.action.args;
        if (a.abstain)
          check(a.first_id === null && a.second_id === null && f.pair === null && mayPass);
        else {
          check(a.first_id !== null && a.second_id !== null && a.first_id !== a.second_id);
          check(
            equal([Math.min(a.first_id, a.second_id), Math.max(a.first_id, a.second_id)], f.pair),
          );
        }
        if (f.pair)
          for (const id of f.pair) {
            check(candidates.includes(id));
            used.add(id);
          }
        history.push({ day, pair: f.pair });
        facts.set(day, { pair: f.pair, index: i });
      }
    }
    if (e.type === "wolf_kill_vote_cast" || e.type === "witch_potion_used")
      check(facts.has(day) || skipped.has(day));
    if (e.type === "night_resolved") {
      check(nightAlive.has(day) && (facts.has(day) || skipped.has(day)) && !resolved.has(day));
      check(Array.isArray(e.payload.deaths));
      resolved.add(day);
      for (const id of e.payload.deaths) {
        check(typeof id === "number" && original.has(id));
        alive.delete(id);
      }
    }
    if (e.type === mapping) {
      const f = readExileMappingFact(e.type, e.payload);
      check(
        f &&
          phase === Phase.Voting &&
          e.audience === undefined &&
          resolved.has(day) &&
          !mapped.has(day) &&
          alive.has(f.requestedId),
      );
      const raw = facts.get(day)?.pair ?? null,
        mp = magic.get(day);
      const pair = raw && mp && equal(raw, mp) ? null : raw;
      const effective = pair
        ? f.requestedId === pair[0]
          ? pair[1]
          : f.requestedId === pair[1]
            ? pair[0]
            : f.requestedId
        : f.requestedId;
      check(f.effectiveId === effective && f.missed === !alive.has(effective));
      expectedExile = f.missed ? null : effective;
      mapped.add(day);
    }
    if (e.type === "voted_out") {
      check(
        mapped.has(day) &&
          expectedExile !== null &&
          e.payload.target === expectedExile &&
          alive.has(expectedExile),
      );
      alive.delete(expectedExile);
      expectedExile = null;
    }
    if (e.type === "wolf_self_destruct") {
      check(
        typeof e.payload.wolfId === "number" &&
          original.get(e.payload.wolfId)?.camp === Camp.Wolf &&
          alive.has(e.payload.wolfId),
      );
      alive.delete(e.payload.wolfId);
    }
    histories.push(structuredClone(history));
    living.push([...alive]);
  }
  const cycle = Math.max(0, ...record.checkpoints.map((c) => c.cycle));
  for (const d of record.decisions) {
    if (!record.finalized && d.day > cycle) continue;
    if (d.stage === "trickster_exchange") {
      const before = history.filter((h) => h.day < d.day),
        spent = new Set(before.flatMap((h) => h.pair ?? []));
      const candidates = nightAlive.get(d.day)?.filter((id) => !spent.has(id));
      check(
        d.actorId === actor &&
          d.request.phase === Phase.Night &&
          candidates &&
          nightAlive.get(d.day)!.includes(actor) &&
          candidates.length >= 2,
      );
      check(equal(d.request.context.trickster_candidates, candidates));
      const last = before.at(-1);
      check(
        d.request.context.trickster_may_pass === !(last?.day === d.day - 1 && last.pair === null),
      );
      if (record.checkpoints.some((c) => c.cycle >= d.day && c.complete)) check(facts.has(d.day));
    } else
      check(
        d.request.context.trickster_candidates === undefined &&
          d.request.context.trickster_may_pass === undefined,
      );
    for (const e of d.request.context.visible_events) {
      if (e.type === exchange || e.type === skip) {
        check(
          d.actorId === actor &&
            record.events.some(
              (source) => source.type === e.type && equal(source.payload, e.payload),
            ),
        );
        const f =
          e.type === exchange
            ? readTricksterExchangeFact(e.type, e.payload)
            : readTricksterSkipFact(e.type, e.payload);
        check(f && f.day <= d.day);
      }
      if (e.type === mapping)
        check(
          readExileMappingFact(e.type, e.payload) &&
            record.events.some(
              (source) => source.type === mapping && equal(source.payload, e.payload),
            ),
        );
    }
  }
  for (const cp of record.checkpoints) {
    check(cp.eventCount >= 0 && cp.eventCount < histories.length);
    if (cp.complete && cp.cycle > 0) check(resolved.has(cp.cycle));
    const players = new Map(cp.players.map((p) => [p.id, p]));
    check(players.size === original.size);
    for (const [id, initial] of original) {
      const p = players.get(id);
      check(
        p &&
          p.role === initial.role &&
          p.camp === initial.camp &&
          p.name === initial.name &&
          p.alive === living[cp.eventCount]!.includes(id),
      );
      if (id === actor)
        check(
          equal(p.privateState, {
            trickster: { policy: "awa_trickster_exile_v1", history: histories[cp.eventCount] },
          }),
        );
      else check(!Object.hasOwn(p.privateState, "trickster"));
    }
  }
}

/**
 * 负责归档机制 verifier 的完整固定装配。输入为 envelope／schema 已验证的 reproduction 数据；
 * 输出为原拒绝或全部审计通过，16步调用和第一失败保持原顺序，不提前捕获可替换函数数组。
 * 贵族独立推导出的 audit 在原位置传给恶魔；其原 RedMoon／nativeStocks 子链仍由恶魔 verifier 消费。
 * 本入口不导入 World、生产结算或 checkpoint 写方，不授予行动权限，不改变归档／规则版本准入。
 * 独立 schema／ID／安全读器只确认结构，历史成功、失败前缀与规则推导仍属于各实际 verifier。
 */
import type { ReproductionRecord } from "../../recording/reproduction";
import { validateInitialIdentityRecord } from "./initial-identity";
import { validateWildChildRecord } from "./wild-child";
import { validateLonelyGirlRecord } from "./lonely-girl";
import { validateGhostBrideRecord } from "../../recording/ghost_bride_record";
import { validateAnimalDreamRecord } from "../../recording/animal_dream_record";
import { validateFragrantPairRecord } from "../../recording/fragrant_pair_seer_record";
import { validateNobleSecretBodyRecord } from "../../recording/noble_secret_body_record";
import { validateDemonHunterRecord } from "../../recording/demon_hunter_record";
import { validateScholarMentorRecord } from "../../recording/scholar_mentor_record";
import { validateMistRavenRecord } from "../../recording/mist_raven_record";
import { validateRadiantEclipseRecord } from "../../recording/radiant_eclipse_record";
import { validateTimeConsortRecord } from "../../recording/time_consort_record";
import { validateWolfSorcererRecord } from "../../recording/wolf_sorcerer_record";
import { validateTricksterRecord } from "../../recording/trickster_record";
import { validateMagicianRecord } from "./magician/validate";
import { validateOrderPrinceRecord } from "../../recording/order_prince_record";

export function verifyReproductionMechanisms(result: ReproductionRecord): void {
  validateInitialIdentityRecord(result);
  validateWildChildRecord(result);
  validateLonelyGirlRecord(result);
  validateGhostBrideRecord(result);
  validateAnimalDreamRecord(result);
  validateFragrantPairRecord(result);
  // 传递的是由归档重建的审计数据，不是运行时 owner、原体或死亡提交回执。
  const noble = validateNobleSecretBodyRecord(result);
  validateDemonHunterRecord(result, noble);
  validateScholarMentorRecord(result);
  validateMistRavenRecord(result);
  validateRadiantEclipseRecord(result);
  validateTimeConsortRecord(result);
  validateWolfSorcererRecord(result);
  validateTricksterRecord(result);
  validateMagicianRecord(result);
  validateOrderPrinceRecord(result);
}

/**
 * 场景测试验证捣蛋鬼录制与独立核验中的放逐目标映射、取消和来源回执。
 * 输入为固定原生动作的真实对局、两种语言及独立删除的映射／checkpoint 证据。
 * 输出以手写实际放逐／终局结果及缺失或错误映射回执的严格拒绝作为独立预期。
 * 不调用计费模型，不改写 fixture 或 Tape 的预期字节。
 */
import { expect, test } from "bun:test";
import { promises as fs } from "node:fs";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { createRandom, type ActionRequest, type ToolCall } from "../../../../src/core";
import { SessionRecordManager } from "../../../../src/recording/session_recorder";
import { runWithSessionRecorder } from "../../../../src/recording/recording_context";
import {
  beginGameReproduction,
  captureCheckpoint,
  currentEngineVersion,
} from "../../../../src/runtime/simulation/reproduction_context";
import { replayReproduction } from "../../../../src/runtime/simulation/replay_reproduction";
import {
  parseReproductionRecord,
  type ReproductionRecord,
  type RecordedCheckpoint,
} from "../../../../src/recording/reproduction";

import { GameEventRecorder } from "../../../../src/runtime/game_event_recorder";
import { createTestTempDirectory } from "../../../support/drivers/temp-directories";
import { tricksterTwelveConfig } from "../../../../src/runtime/scenarios/trickster_twelve";
import { ObservedBot } from "../../../../src/ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../../../src/app/observed-players-action-provider";
import { randomDraws } from "../../../../src/core";
import { validateTricksterRecord } from "../../../../src/recording/trickster_record";
const records = new Map<string, Promise<ReproductionRecord>>();
let version: ReturnType<typeof currentEngineVersion> | undefined;
function recording(locale: "en" | "zh-CN", cancel: boolean, seed = 0): Promise<ReproductionRecord> {
  const policy = locale + ":" + cancel + ":" + seed;
  let result = records.get(policy);
  if (result) return result;
  result = (async () => {
    const config = structuredClone(tricksterTwelveConfig);
    const random = createRandom("trickster-tape:" + policy);
    const context = bootstrapGame(config, { locale, random });
    const strategies = new Map(
      context.playerIds.map((id) => [
        id,
        new ObservedBot(randomDraws(random.fork("players").fork("id:" + id)), "active"),
      ]),
    );
    const native = new ObservedPlayersActionProvider(context.world, strategies);
    const chosen = new Map<number, [number, number]>();
    const root = await createTestTempDirectory("awa-trickster-tape-");
    try {
      const manager = await SessionRecordManager.create(
        {
          sessionId: "game",
          board: "trickster_twelve",
          startedAtIso: new Date().toISOString(),
          locale,
          random: context.random.metadata,
        },
        root,
      );
      const recorder = new GameEventRecorder(
        { world: context.world, replayManager: manager },
        context.phaseManager.getSnapshot().phase,
      );
      let last: RecordedCheckpoint | undefined;
      const provider = {
        async getAction(r: ActionRequest): Promise<ToolCall | null> {
          if (cancel && r.context.stage === "magician_exchange") {
            const candidates = r.context.swap_candidates!;
            const pair: [number, number] = [candidates[0]!, candidates[1]!];
            chosen.set(r.context.day, pair);
            return {
              name: "swap_targets",
              args: { first_id: pair[0], second_id: pair[1], abstain: false },
            };
          }
          if (cancel && r.context.stage === "trickster_exchange") {
            const pair = chosen.get(r.context.day);
            if (pair && pair.every((id) => r.context.trickster_candidates!.includes(id)))
              return {
                name: "swap_exile_targets",
                args: { first_id: pair[1], second_id: pair[0], abstain: false },
              };
          }
          return native.getAction(r);
        },
      };
      await runWithSessionRecorder(manager, async () => {
        const trace = beginGameReproduction(manager, context, {
          engine: await (version ??= currentEngineVersion()),
          boardId: "trickster_twelve",
          ...(void config, {}),
          locale,
          maxDays: 30,
        });
        for (let cycle = 1; cycle <= 30 && !context.phaseManager.getSnapshot().gameOver; cycle++) {
          await context.phaseManager.runSingleCycle(
            { getAction: (r) => trace.decide(r, provider) },
            30,
          );
          last = captureCheckpoint(
            context.world,
            context.phaseManager.getSnapshot(),
            cycle,
            true,
            context.phaseManager.getEvents().length,
          );
          trace.checkpoint(last, context.phaseManager.getEvents());
          recorder.flush(context.phaseManager.getEvents());
        }
        const snapshot = context.phaseManager.getSnapshot();
        expect(snapshot.gameOver).toBe(true);
        expect(snapshot.result!.reason).not.toBe("max_days_reached");
        await manager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: snapshot.result?.winner ?? null,
          finishReason: snapshot.result!.reason,
          gameResult: snapshot.result!,
          players: last!.players.map((p) => ({
            player_id: p.id,
            role: p.role,
            camp: p.camp,
            alive: p.alive,
          })),
        });
      });
      const record = parseReproductionRecord(
        JSON.parse(await fs.readFile(manager.sessionDir + "/reproduction.json", "utf8")),
      );
      const replay = await replayReproduction(record, root);
      expect(replay.snapshot).toEqual(record.checkpoints.at(-1)!.snapshot);
      return record;
    } finally {
      await fs.rm(root, { recursive: true, force: true });
    }
  })();
  records.set(policy, result);
  return result;
}

for (const locale of ["en", "zh-CN"] as const)
  for (const cancel of [false, true])
    test(
      "Trickster complete native Tape and replay/" + locale + "/" + cancel,
      async () => {
        await recording(locale, cancel);
      },
      120000,
    );
const mutations: Array<[string, (r: ReproductionRecord) => void]> = [
  [
    "missing private audience",
    (r) => {
      delete r.events.find((e) => e.type === "trickster_exchange_committed")!.audience;
    },
  ],
  [
    "duplicate pair",
    (r) => {
      r.events.find((e) => e.type === "trickster_exchange_committed")!.payload.pair = [1, 1];
    },
  ],
  [
    "wrong actor",
    (r) => {
      r.events.find((e) => e.type === "trickster_exchange_committed")!.payload.actorId = 999;
    },
  ],
  [
    "future choice",
    (r) => {
      r.events.find((e) => e.type === "trickster_exchange_committed")!.payload.day = 999;
    },
  ],
  [
    "invented candidate",
    (r) => {
      const c = r.decisions.find((d) => d.stage === "trickster_exchange")!.request.context;
      c.trickster_candidates = [...c.trickster_candidates!, 999];
    },
  ],
  [
    "missing pass contract",
    (r) => {
      delete r.decisions.find((d) => d.stage === "trickster_exchange")!.request.context
        .trickster_may_pass;
    },
  ],
  [
    "checkpoint history reset",
    (r) => {
      const p = r.checkpoints.at(-1)!.players.find((p) => p.role === "trickster")!;
      (p.privateState.trickster as { history: unknown[] }).history = [];
    },
  ],
  [
    "cross-player private choice",
    (r) => {
      const e = r.events.find((e) => e.type === "trickster_exchange_committed")!;
      const d = r.decisions.find((d) => d.actorId !== e.payload.actorId)!;
      d.request.context.visible_events = [
        ...d.request.context.visible_events,
        { type: e.type, payload: e.payload } as never,
      ];
    },
  ],
];
for (const [name, mutate] of mutations)
  test(
    "Trickster Tape rejects " + name,
    async () => {
      const r = structuredClone(await recording("en", false));
      mutate(r);
      expect(() => validateTricksterRecord(r)).toThrow("reproduction_trickster_invalid");
    },
    120000,
  );
test("Trickster Tape rejects wrong effective exile and deleted mapping receipt", async () => {
  let source: ReproductionRecord | undefined;
  for (let seed = 0; seed < 8; seed++) {
    const r = await recording("en", false, seed);
    if (r.events.some((e) => e.type === "exile_target_mapped")) {
      source = r;
      break;
    }
  }
  expect(source).toBeDefined();
  if (!source) throw new Error("mapping_fixture_missing");
  const wrong = structuredClone(source),
    e = wrong.events.find((e) => e.type === "exile_target_mapped")!;
  e.payload.effectiveId = 999;
  expect(() => parseReproductionRecord(wrong)).toThrow();
  const missing = structuredClone(source),
    index = missing.events.findIndex((e) => e.type === "exile_target_mapped");
  const removed = missing.events.splice(index, 1)[0]!;
  for (const cp of missing.checkpoints) if (cp.eventCount > index) cp.eventCount--;
  for (const d of missing.decisions)
    d.request.context.visible_events = d.request.context.visible_events.filter(
      (e) =>
        !(e.type === removed.type && JSON.stringify(e.payload) === JSON.stringify(removed.payload)),
    );
  expect(() => parseReproductionRecord(missing)).toThrow();
}, 120000);
